"""Execute real snapshot coordinator with deterministic Android/network doubles."""
from pathlib import Path
import tempfile,subprocess,os
root=Path(__file__).resolve().parents[1]
sources={
'android/content/Context.java':'package android.content;public class Context {public Context getApplicationContext(){return this;}}',
'android/app/Activity.java':'package android.app;public class Activity extends android.content.Context {}',
'android/os/Looper.java':'package android.os;public class Looper {public static Looper getMainLooper(){return new Looper();}}',
'android/os/SystemClock.java':'package android.os;public class SystemClock {public static long now=100000;public static long elapsedRealtime(){return now;}}',
'android/os/Handler.java':'''package android.os;import java.util.*;public class Handler {static class Task{long at;Runnable r;Task(long a,Runnable b){at=a;r=b;}}static final List<Task> tasks=new ArrayList<>();public Handler(Looper l){}public synchronized void post(Runnable r){postDelayed(r,0);}public void postDelayed(Runnable r,long d){synchronized(tasks){tasks.add(new Task(SystemClock.now+d,r));}}public void removeCallbacks(Runnable r){synchronized(tasks){tasks.removeIf(t->t.r==r);}}public static void ready(){while(true){Task t=null;synchronized(tasks){for(Task x:tasks)if(x.at<=SystemClock.now){t=x;break;}if(t!=null)tasks.remove(t);}if(t==null)return;t.r.run();}}}''',
'org/json/JSONException.java':'package org.json;public class JSONException extends Exception {}',
'org/json/JSONArray.java':'''package org.json;import java.util.*;public class JSONArray {List<JSONObject> a=new ArrayList<>();public JSONArray put(JSONObject o){a.add(o);return this;}public int length(){return a.size();}public JSONObject getJSONObject(int i)throws JSONException{return a.get(i);}}''',
'org/json/JSONObject.java':'''package org.json;import java.util.*;public class JSONObject {Map<String,Object> m=new LinkedHashMap<>();public JSONObject(){}static Map<String,Map<String,Object>> registry=new HashMap<>();public JSONObject(String s){Map<String,Object> value=registry.get(s);if(value==null)throw new IllegalArgumentException();m.putAll(value);}public JSONObject put(String k,Object v)throws JSONException{m.put(k,v);return this;}public String getString(String k)throws JSONException{return (String)m.get(k);}public long getLong(String k)throws JSONException{return ((Number)m.get(k)).longValue();}public int getInt(String k)throws JSONException{return (int)getLong(k);}public String optString(String k,String d){return (String)m.getOrDefault(k,d);}public JSONArray getJSONArray(String k)throws JSONException{return (JSONArray)m.get(k);}public int length(){return m.size();}public String toString(){String s=m.toString();registry.put(s,new LinkedHashMap<>(m));return s;}}''',
'in/scrollcount/probe/FriendStore.java':'''package in.scrollcount.probe;import java.util.*;import android.content.*;class FriendStore {static final FriendStore INSTANCE=new FriendStore();boolean on=true;final Prefs prefs=new Prefs();final LinkedHashMap<String,Friend> friends=new LinkedHashMap<>();static FriendStore get(Context c){return INSTANCE;}boolean enabled(){return on;}boolean storedSharing(){return true;}String id(){return "a".repeat(32);}void save(){}static class Friend{String id,name,key="",uploaded="",state="",day="";long reels,shorts,sequence,received;boolean connected;Friend(String i,String n){id=i;name=n;}}static class Prefs{Map<String,Object> m=new HashMap<>();String getString(String k,String d){return (String)m.getOrDefault(k,d);}long getLong(String k,long d){return ((Number)m.getOrDefault(k,d)).longValue();}boolean getBoolean(String k,boolean d){return (Boolean)m.getOrDefault(k,d);}Prefs edit(){return this;}Prefs putString(String k,String v){m.put(k,v);return this;}Prefs putLong(String k,long v){m.put(k,v);return this;}boolean commit(){return true;}void apply(){}}}''',
'in/scrollcount/probe/HistoryStore.java':'''package in.scrollcount.probe;import android.content.*;class HistoryStore{static final HistoryStore INSTANCE=new HistoryStore();Runnable listener;long reels;static HistoryStore get(Context c){return INSTANCE;}void observeCounts(Runnable r){listener=r;}void dailyItems(long a,long b,java.util.function.Consumer<long[]> c){c.accept(new long[]{reels,0,0,1});}void change(long n){reels=n;listener.run();}}''',
'in/scrollcount/probe/DailyBadge.java':'package in.scrollcount.probe;class DailyBadge {static long start(long n){return 0;}static long end(long n){return Long.MAX_VALUE;}}',
'in/scrollcount/probe/HourlyFriendJob.java':'package in.scrollcount.probe;class HourlyFriendJob {static void ensure(android.content.Context c){}}',
'in/scrollcount/probe/FriendApi.java':'''package in.scrollcount.probe;import org.json.*;class FriendApi {static volatile int calls;static boolean hold;static Result pending;static JSONObject reply,last;static JSONArray inbound=new JSONArray();interface Result{void done(JSONObject r,String e);}void request(FriendStore s,String path,String method,JSONObject data,Result r){try{last=data;calls++;JSONArray fs=new JSONArray();for(FriendStore.Friend f:s.friends.values())fs.put(new JSONObject().put("id",f.id).put("name",f.name).put("public_key",f.key));reply=new JSONObject().put("friends",fs).put("snapshots",inbound);if(hold)pending=r;else r.done(reply,"");}catch(Exception e){throw new RuntimeException(e);}}static void release(){hold=false;Result r=pending;pending=null;r.done(reply,"");}}''',
'in/scrollcount/probe/AutomaticSyncTest.java':'''package in.scrollcount.probe;import android.os.*;import java.security.*;public class AutomaticSyncTest {static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static void pump()throws Exception{for(int i=0;i<50;i++){Handler.ready();Thread.sleep(2);}}static void advance(long ms)throws Exception{SystemClock.now+=ms;pump();}public static void main(String[] args)throws Exception{FriendStore store=FriendStore.INSTANCE;KeyPair friend=FriendCipher.create();String bid="b".repeat(32);FriendStore.Friend f=new FriendStore.Friend(bid,"Friend");f.key=FriendCipher.encode(friend.getPublic().getEncoded());store.friends.put(bid,f);FriendSync sync=FriendSync.get(new android.content.Context());HistoryStore h=HistoryStore.INSTANCE;
h.change(1);advance(1999);check(FriendApi.calls==0,"short debounce");advance(1);check(FriendApi.calls==1,"count changes upload without Friends activity");check(sync.status.equals("Up to date"),"background owner completes");
for(int i=2;i<=21;i++)h.change(i);advance(119999);check(FriendApi.calls==1,"rapid skips coalesce");advance(1);check(FriendApi.calls==2,"latest burst uploads once");org.json.JSONObject e=FriendApi.last.getJSONArray("updates").getJSONObject(0);String plain=FriendCipher.decrypt(friend,store.prefs.getString("publicKey",""),store.id(),bid,e.getString("iv"),e.getString("ciphertext"));check(plain.contains("reels=21"),"upload includes newest committed totals");
h.change(22);FriendApi.hold=true;advance(120000);check(FriendApi.calls==3,"delayed network request");h.change(23);FriendApi.release();pump();advance(120000);check(FriendApi.calls==4,"changes during request are not lost");h.change(24);store.on=false;sync.configurationChanged();advance(60000);check(FriendApi.calls==4,"pause cancels queued automatic transfer");store.on=true;sync.configurationChanged();advance(60000);check(FriendApi.calls==4,"no permanent background polling");store.on=true;sync.configurationChanged();org.json.JSONObject data=new org.json.JSONObject().put("v",1).put("day",FriendSnapshot.day(System.currentTimeMillis())).put("reels",12L).put("shorts",4L).put("sequence",1L).put("captured",System.currentTimeMillis());FriendCipher.Envelope incoming=FriendCipher.encrypt(friend,store.prefs.getString("publicKey",""),bid,store.id(),data.toString());FriendApi.inbound=new org.json.JSONArray().put(new org.json.JSONObject().put("sender",bid).put("iv",incoming.iv).put("ciphertext",incoming.ciphertext));
java.lang.reflect.Field vf=FriendSync.class.getDeclaredField("verified");vf.setAccessible(true);
sync.background(true);pump();sync.background(false);check(f.reels==12&&f.shorts==4,"valid incoming snapshot applied");check(((java.util.Map)vf.get(sync)).size()==1,"only verified incoming envelope cached");
int decrypts=FriendCipher.decryptCalls;sync.background(true);pump();sync.background(false);check(f.sequence==1,"unchanged encrypted snapshot does not alter counts");check(FriendCipher.decryptCalls==decrypts,"unchanged authenticated envelope skips decryption");
org.json.JSONObject newer=new org.json.JSONObject().put("v",1).put("day",FriendSnapshot.day(System.currentTimeMillis())).put("reels",19L).put("shorts",5L).put("sequence",2L).put("captured",System.currentTimeMillis());FriendCipher.Envelope next=FriendCipher.encrypt(friend,store.prefs.getString("publicKey",""),bid,store.id(),newer.toString());FriendApi.inbound=new org.json.JSONArray().put(new org.json.JSONObject().put("sender",bid).put("iv",next.iv).put("ciphertext",next.ciphertext));sync.background(true);pump();sync.background(false);check(f.reels==19&&f.sequence==2,"changed envelope reverified and applied");
FriendApi.inbound=new org.json.JSONArray().put(new org.json.JSONObject().put("sender",bid).put("iv",next.iv).put("ciphertext","bad"));sync.background(true);pump();sync.background(false);check(f.reels==19&&f.state.equals("Could not verify saved update"),"invalid ciphertext rejected without losing good totals");sync.configurationChanged();check(((java.util.Map)vf.get(sync)).isEmpty(),"configuration invalidates verification cache");
System.out.println("PASS: actual coordinator auto upload, debounce, burst coalescing, newest totals, in-flight changes, pause cancellation and bounded background ownership");System.exit(0);}}'''
}
jhome=Path(os.environ['JAVA_HOME'])/'bin'
