 d=Path(temp)
 for n,s in sources.items():p=d/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
 actual=root/'app/src/main/java/in/scrollcount/probe'
 cipher=d/'in/scrollcount/probe/FriendCipher.java'
 instrumented=(actual/'FriendCipher.java').read_text().replace('final class FriendCipher {','final class FriendCipher { static int decryptCalls;').replace('        byte[] nonce=decode(iv)', '        decryptCalls++;byte[] nonce=decode(iv)')
 cipher.write_text(instrumented)
 files=[str(p) for p in d.rglob('*.java')]+[str(actual/f) for f in ['FriendSync.java','FriendSnapshot.java','HourlySyncPlan.java','SyncCadence.java']]
 subprocess.run([str(jhome/'javac'),'-d',str(d/'classes'),*files],check=True)
 subprocess.run([str(jhome/'java'),'-cp',str(d/'classes'),'in.scrollcount.probe.AutomaticSyncTest'],check=True,timeout=20)
